"""Plugin uninstall command."""

from __future__ import annotations

import logging
import sys

import rich_click as click

from hcli.lib.console import console
from hcli.lib.ida.plugin.exceptions import PluginNotInstalledError
from hcli.lib.ida.plugin.install import (
    find_installed_plugin,
    sweep_trash,
)
from hcli.lib.ida.plugin.install import uninstall_plugin as uninstall_plugin_impl
from hcli.lib.ida.plugin.reference import parse_dependency_spec

logger = logging.getLogger(__name__)


@click.command()
@click.argument("plugin")
@click.option("--yes", "-y", is_flag=True, default=False, help="Confirm all prompts automatically.")
def uninstall_plugin(plugin: str, yes: bool) -> None:
    """Remove an installed plugin."""
    dep_names: list[str] = []
    try:
        sweep_trash()

        try:
            record = find_installed_plugin(plugin)
            for spec in record.metadata.plugin.dependencies:
                try:
                    dep_names.append(parse_dependency_spec(spec).name)
                except ValueError:
                    pass
        except PluginNotInstalledError:
            pass

        uninstall_plugin_impl(plugin)
    except PluginNotInstalledError as e:
        console.print(f"[red]{e}[/red]")
        raise click.Abort()
    except Exception as e:
        logger.debug("failed to uninstall: %s", e, exc_info=True)
        console.print(f"[red]uninstall failed: {e}[/red]")
        raise click.Abort()

    console.print(f"[green]Uninstalled[/green] plugin: [blue]{plugin}[/blue]")

    if not dep_names:
        return

    installed_deps: list[tuple[str, str | None]] = []
    for name in dep_names:
        try:
            dep_record = find_installed_plugin(name)
            installed_deps.append((name, dep_record.version))
        except PluginNotInstalledError:
            pass
    if not installed_deps:
        return

    console.print("These plugins were listed as dependencies:")
    for name, version in installed_deps:
        version_str = f"=={version}" if version else ""
        console.print(f"  {name}{version_str}")

    interactive = sys.stdin.isatty()
    if yes:
        should_remove = True
    elif interactive:
        should_remove = click.confirm("Remove them too?", default=False)
    else:
        console.print("Remove them manually if no longer needed.")
        return

    if not should_remove:
        return

    for name, _ in installed_deps:
        try:
            uninstall_plugin_impl(name)
            console.print(f"  [green]Uninstalled[/green] dependency: [blue]{name}[/blue]")
        except Exception as e:
            logger.debug("failed to uninstall dependency %s: %s", name, e, exc_info=True)
            console.print(f"  [red]Failed[/red] to uninstall dependency {name}: {e}")

"""Plugin status command."""

from __future__ import annotations

import logging
from typing import Literal

import rich.table
import rich_click as click
from pydantic import BaseModel

from hcli.env import ENV
from hcli.lib.console import console, print_json
from hcli.lib.ida import (
    FailedToDetectIDAVersion,
    MissingCurrentInstallationDirectory,
    explain_failed_to_detect_ida_version,
    explain_missing_current_installation_directory,
    find_current_ida_platform,
    find_current_ida_version,
)
from hcli.lib.ida.plugin import parse_plugin_version
from hcli.lib.ida.plugin.exceptions import AmbiguousPluginReferenceError
from hcli.lib.ida.plugin.install import (
    InstalledPluginRecord,
    find_installed_plugin_in,
    get_installed_legacy_plugins,
    get_installed_minimal_plugins,
    get_installed_plugin_records,
    get_plugins_directory,
)
from hcli.lib.ida.plugin.repo import BasePluginRepo

logger = logging.getLogger(__name__)


class InstalledPluginStatusEntry(BaseModel):
    name: str
    version: str
    installed: Literal[True] = True
    kind: Literal["installed"] = "installed"
    upgrade_checked: bool
    in_repository: bool | None
    upgradable_to: str | None


class NotFoundPluginStatusEntry(BaseModel):
    name: str
    installed: Literal[False] = False


class IncompatiblePluginStatusEntry(BaseModel):
    name: str
    version: str | None
    installed: Literal[True] = True
    kind: Literal["incompatible"] = "incompatible"
    path: str


class LegacyPluginStatusEntry(BaseModel):
    name: str
    version: None = None
    installed: Literal[True] = True
    kind: Literal["legacy"] = "legacy"
    path: str


PluginStatusEntry = (
    InstalledPluginStatusEntry | NotFoundPluginStatusEntry | IncompatiblePluginStatusEntry | LegacyPluginStatusEntry
)


class StatusReport(BaseModel):
    plugins: list[PluginStatusEntry]


def _collect_installed_entry(
    plugin_repo: BasePluginRepo,
    record: InstalledPluginRecord,
    current_platform: str,
    current_ida_version: str,
    skip_upgrade_check: bool,
) -> InstalledPluginStatusEntry:
    if skip_upgrade_check:
        return InstalledPluginStatusEntry(
            name=record.name,
            version=record.version,
            upgrade_checked=False,
            in_repository=None,
            upgradable_to=None,
        )

    try:
        location = plugin_repo.find_compatible_plugin_from_spec(
            record.name, current_platform, current_ida_version, host=record.host
        )
        latest_version = location.metadata.plugin.version
        return InstalledPluginStatusEntry(
            name=record.name,
            version=record.version,
            upgrade_checked=True,
            in_repository=True,
            upgradable_to=(
                latest_version if parse_plugin_version(latest_version) > parse_plugin_version(record.version) else None
            ),
        )
    except (ValueError, KeyError, AmbiguousPluginReferenceError):
        return InstalledPluginStatusEntry(
            name=record.name,
            version=record.version,
            upgrade_checked=True,
            in_repository=False,
            upgradable_to=None,
        )


def _render_status_row(table: rich.table.Table, entry: PluginStatusEntry) -> None:
    if isinstance(entry, IncompatiblePluginStatusEntry):
        table.add_row(
            f"[grey69](incompatible)[/grey69] [blue]{entry.name}[/blue]",
            entry.version or "",
            f"[grey69]found at: $IDAPLUGINS/[/grey69]{entry.path}",
        )
        return

    if isinstance(entry, LegacyPluginStatusEntry):
        table.add_row(
            f"[grey69](legacy)[/grey69] [blue]{entry.name}[/blue]",
            "",
            f"[grey69]found at: $IDAPLUGINS/[/grey69]{entry.path}",
        )
        return

    if isinstance(entry, NotFoundPluginStatusEntry):
        return

    if not entry.upgrade_checked:
        status = "[dim]skipped[/dim]"
    elif not entry.in_repository:
        status = "[yellow]not found in repository[/yellow]"
    elif entry.upgradable_to:
        status = f"upgradable to [yellow]{entry.upgradable_to}[/yellow]"
    else:
        status = ""

    table.add_row(entry.name, entry.version, status)


def collect_status_report(
    plugin_repo: BasePluginRepo,
    plugins: tuple[str, ...],
    skip_upgrade_check: bool,
) -> StatusReport:
    current_platform = find_current_ida_platform()
    current_ida_version = find_current_ida_version()

    all_records = get_installed_plugin_records()

    not_found_names: list[str] = []
    if plugins:
        installed_records = []
        for name in plugins:
            record = find_installed_plugin_in(all_records, name)
            if record is None:
                not_found_names.append(name)
            else:
                installed_records.append(record)
    else:
        installed_records = all_records

    entries: list[PluginStatusEntry] = [
        _collect_installed_entry(plugin_repo, record, current_platform, current_ida_version, skip_upgrade_check)
        for record in installed_records
    ]

    entries.extend(NotFoundPluginStatusEntry(name=name) for name in not_found_names)

    if not plugins:
        plugin_directory = get_plugins_directory()
        for path, metadata in get_installed_minimal_plugins():
            plugin_path = path.parent.relative_to(plugin_directory)
            entries.append(
                IncompatiblePluginStatusEntry(
                    name=metadata.plugin.name,
                    version=metadata.plugin.version or None,
                    path=f"{plugin_path}/",
                )
            )

        for path in get_installed_legacy_plugins():
            entries.append(
                LegacyPluginStatusEntry(
                    name=path.name,
                    path=path.name,
                )
            )

    return StatusReport(plugins=entries)


def render_status_report_text(report: StatusReport, plugins_filter: tuple[str, ...]) -> None:
    table = rich.table.Table(show_header=False, box=None)
    table.add_column("name", style="blue")
    table.add_column("version", style="default")
    table.add_column("status")

    not_found_names: list[str] = []
    has_incompatible = False
    has_legacy = False

    for entry in report.plugins:
        if isinstance(entry, NotFoundPluginStatusEntry):
            not_found_names.append(entry.name)
            continue
        if isinstance(entry, IncompatiblePluginStatusEntry):
            has_incompatible = True
        elif isinstance(entry, LegacyPluginStatusEntry):
            has_legacy = True
        _render_status_row(table, entry)

    if table.row_count:
        console.print(table)
    elif not plugins_filter:
        console.print("[grey69]No plugins found[/grey69]")

    for name in not_found_names:
        console.print(f"[red]Not installed[/red]: {name}")

    if has_incompatible:
        console.print()
        console.print("[yellow]Incompatible plugins[/yellow] don't work with this version of hcli.")
        console.print(
            f"[dim]They might be broken or outdated. Try using `{ENV.HCLI_BINARY_NAME} plugin lint /path/to/plugin`.[/dim]"
        )

    if has_legacy:
        console.print()
        console.print("[yellow]Legacy plugins[/yellow] are old, single-file plugins.")
        console.print("They aren't managed by hcli. Try finding an updated version in the plugin repository.")


def render_status_report_json(report: StatusReport) -> None:
    print_json(report.model_dump(mode="json"))


@click.command()
@click.argument("plugins", nargs=-1)
@click.option(
    "--skip-upgrade-check",
    is_flag=True,
    default=False,
    help="skip the per-plugin upgrade check against the plugin repository",
)
@click.option("--json", "json_output", is_flag=True, default=False, help="output machine-readable JSON")
@click.pass_context
def get_plugin_status(ctx, plugins: tuple[str, ...], skip_upgrade_check: bool, json_output: bool) -> None:
    """Show installed plugins and their upgrade status.

    If one or more PLUGINS are given, show status for just those plugins,
    and exit with a non-zero status if any of them isn't installed.
    """
    plugin_repo: BasePluginRepo = ctx.obj["plugin_repo"]
    try:
        report = collect_status_report(plugin_repo, plugins, skip_upgrade_check)

        if json_output:
            render_status_report_json(report)
        else:
            render_status_report_text(report, plugins)

    except MissingCurrentInstallationDirectory:
        explain_missing_current_installation_directory(console)
        raise click.Abort()

    except FailedToDetectIDAVersion:
        explain_failed_to_detect_ida_version(console)
        raise click.Abort()

    except Exception as e:
        logger.debug("error: %s", e, exc_info=True)
        console.print(f"[red]Error[/red]: {e}")
        raise click.Abort()

    has_not_found = any(isinstance(e, NotFoundPluginStatusEntry) for e in report.plugins)
    if has_not_found:
        ctx.exit(1)

"""Plugin lint command."""

from __future__ import annotations

import io
import logging
import zipfile
from pathlib import Path

import httpx
import rich_click as click
from pydantic import ValidationError

from hcli.lib.console import console
from hcli.lib.ida.plugin import (
    IDAMetadataDescriptor,
    parse_plugin_version,
    validate_metadata_in_plugin_archive,
)
from hcli.lib.ida.plugin.install import validate_metadata_in_plugin_directory
from hcli.lib.ida.plugin.repo import fetch_plugin_archive
from hcli.lib.util.logging import m

logger = logging.getLogger(__name__)


def _lint_readme_in_directory(plugin_path: Path, source_name: str) -> int:
    """Check for README.md file in plugin directory.

    returns: number of recommendations made
    """
    found_files = []
    has_exact_match = False
    recommendation_count = 0

    for item in plugin_path.iterdir():
        if item.is_file() and item.name == "README.md":
            has_exact_match = True
            break
        if item.is_file() and item.name.lower().startswith("readme"):
            found_files.append(item.name)

    if has_exact_match:
        return 0

    if found_files:
        console.print(
            f"[yellow]Recommendation[/yellow] ({source_name}): rename {found_files[0]} to README.md (exact casing)"
        )
        console.print("  Use 'README.md' with exact casing for consistency and discoverability")
        recommendation_count += 1
    else:
        console.print(f"[yellow]Recommendation[/yellow] ({source_name}): add a README.md file")
        console.print("  A README helps users understand what your plugin does and how to use it")
        recommendation_count += 1

    return recommendation_count


def _lint_readme_in_archive(zip_data: bytes, metadata_path: Path, source_name: str) -> int:
    """Check for README.md file in plugin archive.

    returns: number of recommendations made
    """
    plugin_dir = metadata_path.parent
    recommendation_count = 0

    with zipfile.ZipFile(io.BytesIO(zip_data), "r") as zip_file:
        namelist = zip_file.namelist()

        found_files = []
        has_exact_match = False

        for file_path in namelist:
            path_obj = Path(file_path)
            if path_obj.parent == plugin_dir:
                if path_obj.name == "README.md":
                    has_exact_match = True
                    break
                if path_obj.name.lower().startswith("readme"):
                    found_files.append(path_obj.name)

        if has_exact_match:
            return 0

        if found_files:
            console.print(
                f"[yellow]Recommendation[/yellow] ({source_name}): rename {found_files[0]} to README.md (exact casing)"
            )
            console.print("  Use 'README.md' with exact casing for consistency and discoverability")
            recommendation_count += 1
        else:
            console.print(f"[yellow]Recommendation[/yellow] ({source_name}): add a README.md file")
            console.print("  A README helps users understand what your plugin does and how to use it")
            recommendation_count += 1

        return recommendation_count


def _check_unexpected_keys(metadata: IDAMetadataDescriptor, source_name: str) -> int:
    """Check for unexpected keys in the plugin metadata.

    returns: number of recommendations made
    """
    recommendation_count = 0

    if hasattr(metadata.plugin, "__pydantic_extra__") and metadata.plugin.__pydantic_extra__:
        extra_keys = sorted(metadata.plugin.__pydantic_extra__.keys())
        for key in extra_keys:
            console.print(f"[yellow]Warning[/yellow] ({source_name}): unexpected key in plugin metadata: '{key}'")
            console.print("  This key is not part of the ida-plugin.json schema and will be ignored")
            recommendation_count += 1

    return recommendation_count


def _lint_metadata(metadata: IDAMetadataDescriptor, source_name: str) -> int:
    """Validate a single plugin metadata and show lint recommendations.

    returns: number of recommendations made
    """
    recommendation_count = 0

    recommendation_count += _check_unexpected_keys(metadata, source_name)

    if not parse_plugin_version(metadata.plugin.version):
        console.print(f"[red]Error[/red] ({source_name}): plugin version should look like 'X.Y.Z'")
        recommendation_count += 1

    if not metadata.plugin.ida_versions:
        console.print(f"[yellow]Recommendation[/yellow] ({source_name}): ida-plugin.json: provide plugin.idaVersions")
        console.print("  Specify which IDA versions your plugin supports (e.g., ['9.0', '9.1'])")
        recommendation_count += 1

    if not metadata.plugin.description:
        console.print(f"[yellow]Recommendation[/yellow] ({source_name}): ida-plugin.json: provide plugin.description")
        console.print("  A one-line description improves discoverability in the plugin repository")
        recommendation_count += 1

    if not metadata.plugin.categories:
        console.print(f"[yellow]Recommendation[/yellow] ({source_name}): ida-plugin.json: provide plugin.categories")
        console.print("  Categories help users find your plugin (e.g., 'malware-analysis', 'decompilation')")
        recommendation_count += 1

    if not metadata.plugin.logo_path:
        console.print(f"[yellow]Recommendation[/yellow] ({source_name}): ida-plugin.json: provide plugin.logoPath")
        console.print("  A logo image (16:9 aspect ratio) makes your plugin more visually appealing")
        recommendation_count += 1

    if not metadata.plugin.keywords:
        console.print(f"[yellow]Recommendation[/yellow] ({source_name}): ida-plugin.json: provide plugin.keywords")
        console.print("  Keywords improve search discoverability in the plugin repository")
        recommendation_count += 1

    if not metadata.plugin.license:
        console.print(f"[yellow]Recommendation[/yellow] ({source_name}): ida-plugin.json: provide plugin.license")
        console.print("  Specify the license (e.g., 'MIT', 'Apache 2.0') to clarify usage rights")
        recommendation_count += 1

    if not metadata.plugin.authors and not metadata.plugin.maintainers:
        console.print(
            f"[red]Error[/red] ({source_name}): ida-plugin.json: provide plugin.authors or plugin.maintainers"
        )
        console.print("  Contact information is required for authors or maintainers")
        recommendation_count += 1
    else:
        # Check if contacts have both name and email for better completeness
        for i, author in enumerate(metadata.plugin.authors):
            if not author.name:
                console.print(
                    f"[yellow]Recommendation[/yellow] ({source_name}): plugin.authors[{i}]: provide an author name"
                )
                recommendation_count += 1
        for i, maintainer in enumerate(metadata.plugin.maintainers):
            if not maintainer.name:
                console.print(
                    f"[yellow]Recommendation[/yellow] ({source_name}): plugin.maintainers[{i}]: provide a maintainer name"
                )
                recommendation_count += 1

    recommendation_count += _check_dependency_specs(metadata, source_name)

    return recommendation_count


def _check_dependency_specs(metadata: IDAMetadataDescriptor, source_name: str) -> int:
    from hcli.lib.ida.plugin.reference import parse_dependency_spec

    recommendation_count = 0
    for i, spec in enumerate(metadata.plugin.dependencies):
        try:
            parse_dependency_spec(spec)
        except ValueError as e:
            console.print(f"[red]Error[/red] ({source_name}): plugin.dependencies[{i}]: invalid spec '{spec}': {e}")
            recommendation_count += 1
    return recommendation_count


def _lint_plugin_directory(plugin_path: Path) -> int:
    """Lint a plugin in a directory.

    returns: number of recommendations made
    """
    recommendation_count = 0

    metadata_file = plugin_path / "ida-plugin.json"
    if not metadata_file.exists():
        console.print(f"[red]Error[/red]: ida-plugin.json not found in {plugin_path}")
        return 1

    content = metadata_file.read_text(encoding="utf-8")
    try:
        metadata = IDAMetadataDescriptor.model_validate_json(content)
    except ValidationError as e:
        console.print("[red]Error[/red]: ida-plugin.json validation failed")
        for error in e.errors():
            field_path = ".".join(str(loc) for loc in error["loc"])
            error_msg = error["msg"]
            error_type = error["type"]

            if error_type == "missing":
                console.print(f"  [red]Missing required field[/red]: {field_path}")
            else:
                console.print(f"  [red]Invalid value[/red] for {field_path}: {error_msg}")

            recommendation_count += 1

        return recommendation_count

    try:
        validate_metadata_in_plugin_directory(plugin_path)
    except Exception as e:
        console.print(f"[red]Error[/red]: ida-plugin.json validation failed: {e}")
        recommendation_count += 1
        return recommendation_count

    recommendation_count += _lint_metadata(metadata, str(plugin_path))
    recommendation_count += _lint_readme_in_directory(plugin_path, str(plugin_path))

    return recommendation_count


def _lint_plugin_archive(zip_data: bytes, source_name: str) -> int:
    """Lint plugins in a .zip archive from bytes.

    returns: number of recommendations made
    """
    recommendation_count = 0

    plugins_found = []
    with zipfile.ZipFile(io.BytesIO(zip_data), "r") as zip_file:
        for file_path in zip_file.namelist():
            if not file_path.endswith("ida-plugin.json"):
                continue

            logger.debug(m("found metadata path: %s", file_path))
            with zip_file.open(file_path) as f:
                try:
                    metadata = IDAMetadataDescriptor.model_validate_json(f.read().decode("utf-8"))
                except ValidationError as e:
                    logger.debug(m("failed to validate metadata: %s", file_path, path=file_path, error=str(e)))
                    console.print(f"[red]Error[/red] ({source_name}): {file_path}: ida-plugin.json validation failed")
                    for error in e.errors():
                        field_path = ".".join(str(loc) for loc in error["loc"])
                        error_msg = error["msg"]
                        error_type = error["type"]

                        if error_type == "missing":
                            console.print(f"  [red]Missing required field[/red]: {field_path}")
                        else:
                            console.print(f"  [red]Invalid value[/red] for {field_path}: {error_msg}")
                        recommendation_count += 1
                    continue
                else:
                    logger.debug(m("found valid metadata: %s", file_path))
                    plugins_found.append((Path(file_path), metadata))

    for path, meta in plugins_found:
        logger.debug("found plugin %s at %s", meta.plugin.name, path)

    if not plugins_found:
        console.print(f"[red]Error[/red]: No valid plugins found in archive {source_name}")
        recommendation_count += 1
        return recommendation_count

    for metadata_path, metadata in plugins_found:
        plugin_source_name = f"{source_name}:{metadata_path}"

        try:
            validate_metadata_in_plugin_archive(zip_data, metadata_path, metadata)
        except ValidationError as e:
            console.print(
                f"[red]Error[/red] ({plugin_source_name}): {metadata_path}: ida-plugin.json validation failed"
            )
            for error in e.errors():
                field_path = ".".join(str(loc) for loc in error["loc"])
                error_msg = error["msg"]
                error_type = error["type"]

                if error_type == "missing":
                    console.print(f"  [red]Missing required field[/red]: {field_path}")
                else:
                    console.print(f"  [red]Invalid value[/red] for {field_path}: {error_msg}")
                recommendation_count += 1

            continue

        except Exception as e:
            console.print(f"[red]Error[/red]: {metadata_path}: ida-plugin.json validation failed: {e}")
            recommendation_count += 1
            continue

        recommendation_count += _lint_metadata(metadata, plugin_source_name)
        recommendation_count += _lint_readme_in_archive(zip_data, metadata_path, plugin_source_name)

    return recommendation_count


@click.command()
@click.argument(
    "path",
    metavar="PATH|URL",
)
def lint_plugin_directory(path: str) -> None:
    """Lint an IDA plugin directory, archive (.zip file), or HTTPS URL."""
    recommendation_count = 0
    if path.startswith("https://"):
        logger.info("linting from HTTP URL")
        try:
            buf = fetch_plugin_archive(path)
        except (httpx.ConnectError, httpx.TimeoutException):
            console.print(f"[red]Cannot connect to {path} - network unavailable.[/red]")
            console.print("Please check your internet connection.")
            raise click.Abort()
        except Exception as e:
            console.print(f"[red]Error[/red]: Failed to fetch archive from {path}: {e}")
            raise click.Abort()

        recommendation_count = _lint_plugin_archive(buf, path)

    else:
        plugin_path = Path(path).expanduser().resolve()
        if not plugin_path.exists():
            console.print(f"[red]Error[/red]: Path does not exist: {plugin_path}")
            raise click.Abort()

        if plugin_path.is_file():
            if plugin_path.suffix.lower() != ".zip":
                console.print(f"[red]Error[/red]: File must be a .zip archive: {plugin_path}")
                raise click.Abort()

            zip_data = plugin_path.read_bytes()
            recommendation_count = _lint_plugin_archive(zip_data, str(plugin_path))
        elif plugin_path.is_dir():
            recommendation_count = _lint_plugin_directory(plugin_path)
        else:
            console.print(f"[red]Error[/red]: Path must be a directory or .zip file: {plugin_path}")
            raise click.Abort()

    if not recommendation_count:
        console.print("[green]no recommendations[/green]")

def get_metadata_from_plugin_directory(plugin_path: Path) -> IDAMetadataDescriptor:
    metadata_file = plugin_path / "ida-plugin.json"
    if not metadata_file.exists():
        raise ValueError(f"ida-plugin.json not found in {plugin_path}")

    try:
        content = metadata_file.read_text(encoding="utf-8")
        return IDAMetadataDescriptor.model_validate_json(content)
    except Exception as e:
        logger.debug("failed to validate ida-plugin.json: %s", e)
        raise ValueError(f"Failed to parse ida-plugin.json in {plugin_path}: {e}")


# TODO: keep this in sync with validate_metadata_in_plugin_archive
def validate_metadata_in_plugin_directory(plugin_path: Path):
    """validate the `ida-plugin.json` metadata within the given plugin directory.

    The following things must be checked:
    - the following paths must contain relative paths, no paths like ".." or similar escapes:
      - entry point
      - logo path
    - the file paths must exist in the directory:
      - entry point
      - logo path
    """
    metadata = get_metadata_from_plugin_directory(plugin_path)

    validate_path(metadata.plugin.entry_point, "entry point")
    if metadata.plugin.logo_path:
        validate_path(metadata.plugin.logo_path, "logo path")

    entry_point_path = plugin_path / metadata.plugin.entry_point

    if metadata.plugin.entry_point.endswith(".py"):
        # source plugin
        if not entry_point_path.exists():
            logger.debug(f"Entry point file not found in directory: '{metadata.plugin.entry_point}'")
            raise ValueError(f"Entry point file not found in directory: '{metadata.plugin.entry_point}'")
    else:
        # binary plugin - check for various extensions
        if not entry_point_path.exists():
            found = False
            for extension in (".so", ".dll", ".dylib"):
                if (plugin_path / (metadata.plugin.entry_point + extension)).exists():
                    found = True
                    break
            if not found:
                logger.debug(f"Entry point file not found in directory: '{metadata.plugin.entry_point}'")
                raise ValueError(f"Entry point file not found in directory: '{metadata.plugin.entry_point}'")

    if metadata.plugin.logo_path:
        logo_path = plugin_path / metadata.plugin.logo_path
        if not logo_path.exists():
            logger.debug(f"Logo file not found in directory: '{metadata.plugin.logo_path}'")
            raise ValueError(f"Logo file not found in directory: '{metadata.plugin.logo_path}'")


def is_valid_plugin_directory(path: Path) -> bool:
    """Does the path hold a well-formed installed plugin?

    Mirrors the criteria of ``get_installed_plugin_records``: the manifest
    parses, referenced files exist, and the plugin name matches the directory
    name. A directory that fails this is debris, e.g. remnants of an
    interrupted uninstall (issue #228).
    """
    if not (path / "ida-plugin.json").exists():
        return False

    try:
        validate_metadata_in_plugin_directory(path)
        metadata = get_metadata_from_plugin_directory(path)
    except ValueError:
        return False

    return metadata.plugin.name == path.name


@dataclass(frozen=True)
class InstalledPluginRecord:
    """An installed plugin and its on-disk metadata."""

    path: Path
    metadata: IDAMetadataDescriptor

    @property
    def name(self) -> str:
        return self.metadata.plugin.name

    @property
    def version(self) -> str:
        return self.metadata.plugin.version

    @property
    def host(self) -> str:
        return self.metadata.plugin.host


def get_installed_plugin_records() -> list[InstalledPluginRecord]:
    """Enumerate installed plugins with their on-disk metadata.

    This is the canonical source of truth for "what is installed". Other
    helpers (``get_installed_plugin_paths``, ``is_plugin_installed``, etc.)
    are implemented on top of this list so they agree on what counts as
    installed.
    """
    plugins_dir = get_plugins_directory()
    records: list[InstalledPluginRecord] = []

    if not plugins_dir.exists():
        return records

    for plugin_path in plugins_dir.iterdir():
        if not plugin_path.is_dir():
            continue

        metadata_file = plugin_path / "ida-plugin.json"
        if not metadata_file.exists():
            continue

        try:
            validate_metadata_in_plugin_directory(plugin_path)
        except ValueError as e:
            logger.debug(f"Invalid plugin metadata in {plugin_path}: {e}")
            continue

        try:
            metadata = get_metadata_from_plugin_directory(plugin_path)
        except ValueError as e:
            logger.warning(f"Failed to read metadata from {plugin_path}: {e}")
            continue

        if metadata.plugin.name != plugin_path.name:
            logger.debug("plugin name and path mismatch")
            continue

        records.append(InstalledPluginRecord(path=plugin_path, metadata=metadata))

    return records


def find_installed_plugin_in(
    records: list[InstalledPluginRecord],
    name: str,
    host: str | None = None,
) -> InstalledPluginRecord | None:
    """Search *pre-fetched* records for a plugin by name and optional host.

    Returns ``None`` when no match is found (does not raise).
    """
    wanted_name = name.lower()
    wanted_host = normalize_plugin_host(host) if host else None

    for record in records:
        if record.name.lower() != wanted_name:
            continue
        if wanted_host is not None and normalize_plugin_host(record.host) != wanted_host:
            continue
        return record

    return None


def find_installed_plugin(name: str, host: str | None = None) -> InstalledPluginRecord:
    """Find an installed plugin by name, optionally qualified by host.

    Name matching is case-insensitive because the user may type a different
    case than the on-disk directory. Host matching, when supplied, is done
    after normalization.

    Raises:
        PluginNotInstalledError: when no matching installed plugin exists.
    """
    record = find_installed_plugin_in(get_installed_plugin_records(), name, host)
    if record is None:
        raise PluginNotInstalledError(name)
    return record


def resolve_installed_plugin_directory(name: str) -> Path:
    """Resolve the on-disk directory for an installed plugin by name.

    Case-insensitive. Used by local commands (uninstall, config) so typing
    ``PLUGIN1`` finds ``$IDAUSR/plugins/plugin1``.

    Raises:
        PluginNotInstalledError: when no matching installed plugin exists.
    """
    return find_installed_plugin(name).path


def get_installed_plugin_paths() -> list[Path]:
    return [r.path for r in get_installed_plugin_records()]


@dataclass
class PluginDependencyInfo:
    name: str
    dependencies: list[str]


def collect_plugin_dependencies() -> list[PluginDependencyInfo]:
    """Enumerate installed plugins that have Python dependencies.

    Skips plugins with unreadable metadata or no dependencies.
    """
    result: list[PluginDependencyInfo] = []
    for record in get_installed_plugin_records():
        try:
            deps = get_python_dependencies_from_plugin_directory(record.path, record.metadata)
        except Exception as e:
            logger.debug("skipping unreadable plugin dependencies at %s: %s", record.path, e)
            continue
        if deps:
            result.append(PluginDependencyInfo(name=record.name, dependencies=deps))
    return result


@dataclass
class PluginDependencyResult:
    name: str
    dependencies: list[str]
    success: bool
    error: str | None = None


def install_single_plugin_dependencies(
    python_exe: Path,
    plugin: PluginDependencyInfo,
    pip_options: PipOptions = PIP_OPTIONS_DEFAULT,
) -> PluginDependencyResult:
    """Install Python dependencies for a single plugin. Does not raise."""
    try:
        pip_install_packages(python_exe, plugin.dependencies, pip_options=pip_options)
        return PluginDependencyResult(name=plugin.name, dependencies=plugin.dependencies, success=True)
    except CantInstallPackagesError as e:
        return PluginDependencyResult(name=plugin.name, dependencies=plugin.dependencies, success=False, error=str(e))


def get_installed_minimal_plugins() -> list[tuple[Path, MinimalIDAPluginMetadata]]:
    """fetch (name, path) pairs for currently installed minimal (likely legacy) plugins"""
    plugins_dir = get_plugins_directory()
    installed_plugins: list[tuple[Path, MinimalIDAPluginMetadata]] = []

    if not plugins_dir.exists():
        return installed_plugins

    for plugin_path in plugins_dir.iterdir():
        if not plugin_path.is_dir():
            continue

        metadata_file = plugin_path / "ida-plugin.json"
        if not metadata_file.exists():
            continue

        try:
            _ = get_metadata_from_plugin_directory(plugin_path)
        except ValueError:
            pass
        else:
            # skip the valid plugins
            continue

        try:
            metadata = MinimalIDAPluginMetadata.model_validate_json(metadata_file.read_bytes())
        except ValueError as e:
            logger.debug(f"Invalid plugin metadata in {plugin_path}: {e}")
            continue

        installed_plugins.append((metadata_file, metadata))

    return installed_plugins


def get_installed_legacy_plugins() -> list[Path]:
    """fetch paths for  currently installed legacy, single-file plugins"""
    plugins_dir = get_plugins_directory()
    installed_plugins: list[Path] = []

    if not plugins_dir.exists():
        return installed_plugins

    for plugin_path in plugins_dir.iterdir():
        if plugin_path.is_dir():
            continue

        if plugin_path.name.endswith(".py"):
            installed_plugins.append(plugin_path)

        if plugin_path.name.endswith((".so", ".dll", ".dylib")):
            installed_plugins.append(plugin_path)

    return installed_plugins


def resolve_python_for_dependencies(python_dependencies: list[str], *, check_environment: bool = True) -> Path:
    """Find IDA's Python and, unless disabled, refuse environments where installing into it is pointless.

    The environment check prints warnings to stderr for non-recommended but
    workable setups and raises for setups where the packages would never reach
    IDA (no venv, wrong Python version, PEP 668, uv overlay, no pip).

    Raises:
        PythonNotFoundError: when IDA's Python can't be determined.
        DependencyInstallationError: when the environment check finds errors.
        PipNotAvailableError: when pip is missing and the environment check was skipped.
    """
    resolved = resolve_current_python()
    if check_environment:
        try:
            validate_python_environment(resolved)
        except PythonEnvironmentError as e:
            raise DependencyInstallationError(python_dependencies, str(e)) from e

    if not has_pip(resolved.exe):
        logger.debug("pip not available")
        raise PipNotAvailableError(resolved.exe)

    return resolved.exe


def validate_can_install_python_dependencies(
    zip_data: bytes,
    metadata: IDAMetadataDescriptor,
    excluded_plugins: list[str] | None = None,
    python_exe: Path | None = None,
    pip_options: PipOptions = PIP_OPTIONS_DEFAULT,
    check_environment: bool = True,
) -> Path | None:
    """Verify Python dependencies can be installed.

    Returns:
        The Python executable path if dependencies were validated, None if no dependencies needed.

    Raises:
        PipNotAvailableError: If pip is not available in IDA's Python
        DependencyInstallationError: If dependencies cannot be installed, including when
            IDA's Python environment fails the health check (see `validate_python_environment`).
    """
    python_dependencies = get_python_dependencies_from_plugin_archive(zip_data, metadata)
    if python_dependencies:
        all_python_dependencies: list[str] = []
        for existing_plugin_path in get_installed_plugin_paths():
            existing_metadata = get_metadata_from_plugin_directory(existing_plugin_path)
            if excluded_plugins and existing_metadata.plugin.name in excluded_plugins:
                continue

            existing_deps = get_python_dependencies_from_plugin_directory(existing_plugin_path, existing_metadata)
            all_python_dependencies.extend(existing_deps)

        all_python_dependencies.extend(python_dependencies)

        if python_exe is None:
            python_exe = resolve_python_for_dependencies(python_dependencies, check_environment=check_environment)
        elif not has_pip(python_exe):
            logger.debug("pip not available")
            raise PipNotAvailableError(python_exe)
        logger.debug(f"python: {python_exe}")

        try:
            verify_pip_can_install_packages(python_exe, all_python_dependencies, pip_options=pip_options)
        except CantInstallPackagesError as e:
            logger.debug("can't install dependencies: %s", e)
            raise DependencyInstallationError(python_dependencies, str(e)) from e

        return python_exe

    return None


def validate_can_install_plugin(
    zip_data: bytes,
    metadata: IDAMetadataDescriptor,
    current_platform: str,
    current_version: str,
    pip_options: PipOptions = PIP_OPTIONS_DEFAULT,
    check_environment: bool = True,
) -> Path | None:
    """Verify plugin can be installed.

    Returns:
        The Python executable path if pip dependencies were validated, None otherwise.

    Raises:
        InvalidPluginNameError: If plugin name is invalid
        PluginAlreadyInstalledError: If plugin is already installed
        BrokenPluginInstallationError: If remnants of a broken installation are in the way
        PlatformIncompatibleError: If current platform is not supported
        IDAVersionIncompatibleError: If current IDA version is not supported
        PipNotAvailableError: If pip is not available (when dependencies are needed)
        DependencyInstallationError: If dependencies cannot be installed
    """
    name = metadata.plugin.name
    try:
        destination_path = get_plugin_directory(name)
    except ValueError as e:
        logger.error(f"Can't install plugin: {e!s}")
        raise InvalidPluginNameError(name, str(e)) from e

